mapper.update:
update sys_user su
set su.password=#{password}
where su.account = #{account}

mapper.insert:
insert into sys_user (account, username, password, salt, email, mobile, status, create_time, name,image_id, remark) values
    (#{user.account},#{user.username},#{user.password}
    ,#{user.salt},#{user.email},#{user.mobile},#{user.status}
    ,#{user.createTime},#{user.name},#{user.imageId},#{user.remark})
